import inventory from "./content-modified.json";
import type { StaticRoute } from "./seo-routes";

/**
 * Source commit dates for sitemap `lastmod`, generated by `bun run seo:dates`.
 * Checked in because Docker and source archives have no Git history.
 */
export interface ContentModifiedInventory {
  routes: Record<string, string>;
  docs: Record<string, string>;
  templates: Record<string, string>;
}

export const contentModified: ContentModifiedInventory = inventory;

export function routeModified(route: StaticRoute): string | undefined {
  return contentModified.routes[route];
}

/** `file` is the filename inside `content/docs`, e.g. `web-en.md`. */
export function docModified(file: string): string | undefined {
  return contentModified.docs[file];
}

export function templateModified(slug: string): string | undefined {
  return contentModified.templates[slug];
}

export function docSourceFile(slug: string, locale: "de" | "en"): string {
  return `${slug || "index"}${locale === "en" ? "-en" : ""}.md`;
}
